protected void connect() throws IOException, FTPException, LoginCanceledException {
    synchronized (this) {
        try {
            SessionPool.instance().add(this);
            this.fireConnectionWillOpenEvent();
            this.message(NSBundle.localizedString("Opening FTP connection to", "Status", "") + " " + host.getHostname() + "...");
            this.log("=====================================");
            this.log(new java.util.Date().toString());
            this.log(host.getIp());
            this.FTP = new FTPClient(host.getEncoding(), new FTPMessageListener() {
                public void logCommand(String cmd) {
                    FTPSession.this.log(cmd);
                }

                public void logReply(String reply) {
                    FTPSession.this.log(reply);
                }
            });
            this.FTP.connect(host.getHostname(), host.getPort(), Preferences.instance().getInteger("connection.timeout"));
            this.FTP.setStrictReturnCodes(true);
            if (Proxy.isSOCKSProxyEnabled()) {
                log.info("Using SOCKS Proxy");
                FTPClient.initSOCKS(Proxy.getSOCKSProxyPort(), Proxy.getSOCKSProxyHost());
            } else {
                FTPClient.clearSOCKS();
            }
            this.FTP.setConnectMode(host.getFTPConnectMode());
            this.message(NSBundle.localizedString("FTP connection opened", "Status", ""));
            this.login();
            if (Preferences.instance().getBoolean("ftp.sendSystemCommand")) {
                host.setIdentification(this.FTP.system());
            }
            this.parser = new DefaultFTPFileEntryParserFactory().createFileEntryParser(host.getIdentification());
            this.fireConnectionDidOpenEvent();
        } catch (SecurityException e) {
            this.log("Security error occurred: " + e.getMessage());
            throw new FTPException("Security error: " + e.getMessage(), e);
        } catch (IllegalArgumentException e) {
            this.log("Invalid argument: " + e.getMessage());
            throw new FTPException("Invalid argument: " + e.getMessage(), e);
        } catch (NumberFormatException e) {
            this.log("Number format error: " + e.getMessage());
            throw new FTPException("Number format error: " + e.getMessage(), e);
        }
    }
}
